ALTER TABLE public.directed_bell_usage ADD COLUMN last_rang_at timestamptz;
CREATE FUNCTION public.save_typed_vehicle_route_points(_from text,_to text,_vehicle text,_tons integer,_from_lat float8,_from_lng float8,_to_lat float8,_to_lng float8) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid; BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; IF _from_lat NOT BETWEEN -90 AND 90 OR _to_lat NOT BETWEEN -90 AND 90 OR _from_lng NOT BETWEEN -180 AND 180 OR _to_lng NOT BETWEEN -180 AND 180 OR _from_lat IS NULL OR _to_lat IS NULL OR _from_lng IS NULL OR _to_lng IS NULL OR public.straight_line_km(_from_lat,_from_lng,_to_lat,_to_lng)<=0 THEN RAISE EXCEPTION 'VALID_COORDINATES_REQUIRED'; END IF; rid:=public.save_detailed_vehicle_route(_from,_to,_vehicle,_tons); INSERT INTO public.vehicle_route_points(route_id,user_id,from_lat,from_lng,to_lat,to_lng) VALUES(rid,auth.uid(),_from_lat,_from_lng,_to_lat,_to_lng) ON CONFLICT(route_id) DO UPDATE SET from_lat=excluded.from_lat,from_lng=excluded.from_lng,to_lat=excluded.to_lat,to_lng=excluded.to_lng; RETURN rid; END $$;
REVOKE ALL ON FUNCTION public.save_typed_vehicle_route_points(text,text,text,integer,float8,float8,float8,float8) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_typed_vehicle_route_points(text,text,text,integer,float8,float8,float8,float8) TO authenticated;
CREATE OR REPLACE FUNCTION public.my_prime99() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('active',public.work_access_internal(auth.uid()),'bell_active',public.work_access_internal(auth.uid()),'alerts_ready',public.paid_alert_ready(auth.uid()),'ends_at',(SELECT max(ends_at) FROM (SELECT ends_at FROM public.prime99_payments WHERE user_id=auth.uid() AND payment_purpose='membership' AND status='approved' UNION ALL SELECT ends_at FROM public.membership_access WHERE user_id=auth.uid() AND revoked_at IS NULL AND starts_at<=now()) a),'provisional',false,'amount',CASE WHEN public.has_paid_bell(auth.uid()) THEN 100 ELSE 49 END,'scope',CASE WHEN public.has_paid_bell(auth.uid()) THEN 'all' ELSE 'work' END); $$;
CREATE OR REPLACE FUNCTION public.my_membership_price() RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN EXISTS(SELECT 1 FROM public.account_programs WHERE user_id=auth.uid() AND member_kind IN('seeker','employer','service')) THEN 49 ELSE 100 END; $$;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='consume_directed_bell'; def:=replace(def,'SELECT rings INTO n','SELECT rings INTO n'); def:=replace(def,'paid:=CASE','IF EXISTS(SELECT 1 FROM public.directed_bell_usage WHERE sender_id=caller AND recipient_id=_target AND last_rang_at>now()-interval ''3 seconds'') THEN RETURN; END IF; paid:=CASE'); def:=replace(def,'SET rings=rings+1','SET rings=rings+1,last_rang_at=now()'); EXECUTE def;
SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='run_main_bell_batch'; def:=regexp_replace(def,' AND EXISTS\(SELECT 1 FROM public.posts own WHERE own.user_id=caller.*?\)\) ORDER BY v.id',' ORDER BY v.id','n'); EXECUTE def;
END $$;
CREATE OR REPLACE FUNCTION public.dispatch_approximate_route_alerts() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.approximate_route_alerts; p public.posts; notice uuid; total integer:=0; previous text:=coalesce(current_setting('app.bell_notice',true),''); BEGIN IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'SERVICE_ONLY'; END IF; FOR q IN SELECT * FROM public.approximate_route_alerts WHERE processed_at IS NULL ORDER BY created_at LIMIT 100 FOR UPDATE SKIP LOCKED LOOP SELECT * INTO p FROM public.posts WHERE id=q.post_id; IF p.id IS NULL OR NOT public.post_listing_visible(p) OR NOT public.has_paid_bell(q.user_id) OR NOT public.bell_route_within_radius(p.id,NULL,q.user_id) OR NOT EXISTS(SELECT 1 FROM public.vehicle_route_preferences WHERE id=q.route_id AND user_id=q.user_id AND enabled AND lower(trim(vehicle_type))=lower(trim(p.vehicle_type))) THEN UPDATE public.approximate_route_alerts SET processed_at=now() WHERE id=q.id; CONTINUE; END IF; PERFORM 1 FROM public.profiles WHERE id=q.user_id FOR UPDATE; IF NOT public.can_notify(q.user_id) THEN CONTINUE; END IF; IF EXISTS(SELECT 1 FROM public.notifications WHERE user_id=q.user_id AND (post_id=p.id OR matched_post_id=p.id)) THEN UPDATE public.approximate_route_alerts SET processed_at=now() WHERE id=q.id; CONTINUE; END IF; PERFORM set_config('app.bell_notice','owner',true); notice:=NULL; INSERT INTO public.notifications(user_id,post_id,message) VALUES(q.user_id,p.id,public.vehicle_bell_route(p.from_place,p.to_place)) RETURNING id INTO notice; IF notice IS NOT NULL THEN UPDATE public.approximate_route_alerts SET processed_at=now(),notification_id=notice WHERE id=q.id;total:=total+1; END IF; END LOOP; PERFORM set_config('app.bell_notice',previous,true); RETURN total; END $$;